// WheelmapLayer Component - Displays accessible places using official Accessibility Cloud widget
import React, { useState, useEffect, useCallback } from 'react';
import mapboxgl from 'mapbox-gl';

const WheelmapLayer = ({
  isVisible,
  map,
  bounds,
  onLayerToggle,
  isDarkMode = false
}) => {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [markers, setMarkers] = useState([]);
  const [places, setPlaces] = useState([]);
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [wheelchairFilter, setWheelchairFilter] = useState('yes');

  // Load accessible places when layer becomes visible
  useEffect(() => {
    console.log('🔍 WheelmapLayer visibility changed:', { isVisible, hasMap: !!map, hasBounds: !!bounds });

    if (isVisible && map && bounds) {
      console.log('✅ Conditions met, loading accessibility places');
      loadAccessiblePlaces();
    } else if (!isVisible) {
      console.log('❌ Layer not visible, clearing markers and places');
      clearMarkers();
      setPlaces([]);
    } else {
      console.log('⚠️ Layer visible but missing requirements:', { map: !!map, bounds: !!bounds });
    }
  }, [isVisible, map, bounds, selectedCategory, wheelchairFilter]);

  // Load accessible places using local API (bypassing widget issues)
  const loadAccessiblePlaces = useCallback(async () => {
    if (!map || !bounds) return;

    setLoading(true);
    setError(null);

    try {
      const searchBounds = {
        north: bounds.getNorth(),
        south: bounds.getSouth(),
        east: bounds.getEast(),
        west: bounds.getWest()
      };

      // Calculate center coordinates from bounds
      const centerLat = (searchBounds.north + searchBounds.south) / 2;
      const centerLng = (searchBounds.west + searchBounds.east) / 2;

      console.log('🔍 WheelmapLayer: Loading accessibility data from local API...');

      // Use local API directly instead of widget
      await loadFromLocalAPI(centerLat, centerLng);

    } catch (error) {
      console.error('❌ Error loading accessibility data:', error);
      console.log('🧪 Creating test markers as final fallback');
      createTestMarkers();
    } finally {
      setLoading(false);
    }
  }, [map, bounds, selectedCategory, wheelchairFilter]);

  // Load the official Accessibility Cloud widget
  const loadAccessibilityCloudWidget = () => {
    return new Promise((resolve, reject) => {
      // Check if already loaded
      if (window.AccessibilityCloud) {
        console.log('✅ Accessibility Cloud widget already loaded');
        resolve();
        return;
      }

      // Set up the callback that the widget will call when loaded
      window.onAccessibilityCloudLoaded = function (AccessibilityCloud) {
        console.log('✅ Accessibility Cloud widget loaded and ready');
        window.AccessibilityCloud = AccessibilityCloud;
        resolve();
      };

      // Check if script is already in the DOM
      const existingScript = document.querySelector('script[src*="accessibility-cloud-js"]');
      if (existingScript) {
        console.log('✅ Accessibility Cloud script already in DOM');
        return;
      }

      // Load CSS first
      const cssLink = document.createElement('link');
      cssLink.rel = 'stylesheet';
      cssLink.href = 'https://cdn.jsdelivr.net/gh/sozialhelden/accessibility-cloud-js@3.2.1/build/example/accessibility.cloud-3.2.1-2350f78a.css';
      document.head.appendChild(cssLink);
      console.log('📦 Loaded Accessibility Cloud CSS');

      // Load JavaScript
      const script = document.createElement('script');
      script.src = 'https://cdn.jsdelivr.net/gh/sozialhelden/accessibility-cloud-js@3.2.1/build/example/accessibility.cloud-3.2.1-21a6710d.min.js';
      script.async = true;
      script.defer = true;

      script.onload = () => {
        console.log('📜 Accessibility Cloud script loaded, waiting for callback...');
      };

      script.onerror = () => {
        console.error('❌ Failed to load Accessibility Cloud widget script');
        reject(new Error('Failed to load widget script'));
      };

      document.head.appendChild(script);
      console.log('📜 Loading Accessibility Cloud script...');
    });
  };

  // Initialize the widget with current coordinates
  const initializeAccessibilityCloudWidget = (centerLat, centerLng, retryCount = 0) => {
    console.log('🚀 Initializing Accessibility Cloud widget with coordinates:', centerLat, centerLng);

    if (!window.AccessibilityCloud) {
      if (retryCount < 5) {
        console.log(`⏳ Accessibility Cloud widget not ready yet, retrying... (${retryCount + 1}/5)`);
        setTimeout(() => {
          initializeAccessibilityCloudWidget(centerLat, centerLng, retryCount + 1);
        }, 500);
        return;
      } else {
        console.error('❌ Accessibility Cloud widget failed to load after 5 retries');
        setError('Widget failed to load');
        return;
      }
    }

    console.log('✅ Accessibility Cloud widget found, proceeding with initialization');

    // Create container for the widget (hidden)
    const containerId = 'accessibility-cloud-widget-container';
    let container = document.getElementById(containerId);
    if (!container) {
      container = document.createElement('div');
      container.id = containerId;
      container.style.display = 'none'; // Hide the default widget UI
      document.body.appendChild(container);
      console.log('📦 Created hidden widget container');
    }

    // Widget configuration
    const config = {
      token: 'eb848ae2fbaff7680ff34a9f31eabf06',
      locale: 'en_US',
      requestParameters: {
        latitude: centerLat,
        longitude: centerLng,
        accuracy: 10000, // 10km radius
        limit: 100, // Get more results
        filter: wheelchairFilter === 'yes' ? 'at-least-partially-accessible-by-wheelchair' : undefined,
      },
      onDataLoaded: (data) => {
        console.log('🎯 Accessibility Cloud data loaded:', data ? data.length : 'undefined', 'places');
        console.log('📊 Raw data sample:', data ? data.slice(0, 2) : 'No data');

        // Update places state for UI
        setPlaces(data || []);

        if (data && data.length > 0) {
          console.log('✅ Processing', data.length, 'places for markers');
          createMarkersFromWidgetData(data);
        } else {
          console.log('⚠️ No data received from widget');
          clearMarkers();
        }
      },
      onPlaceClick: (place) => {
        console.log('📍 Place clicked:', place);
      },
      onError: (error) => {
        console.error('❌ Accessibility Cloud widget error:', error);
        setError(error.message);

        // Fallback: Create test markers around Halifax to verify marker system works
        console.log('🔄 Creating test markers as fallback...');
        createTestMarkers();
      }
    };

    // Initialize the widget
    try {
      window.AccessibilityCloud.render(container, config);
      console.log('✅ Accessibility Cloud widget initialized successfully');
    } catch (error) {
      console.error('❌ Failed to render Accessibility Cloud widget:', error);
      setError('Failed to initialize widget');
    }
  };

  // Fallback to local API if widget fails
  const loadFromLocalAPI = async (centerLat, centerLng) => {
    console.log('🔄 Loading accessibility data from local API as fallback');

    const bounds = {
      west: centerLng - 0.05, // ~5km west
      south: centerLat - 0.05, // ~5km south
      east: centerLng + 0.05, // ~5km east
      north: centerLat + 0.05 // ~5km north
    };

    try {
      // Use our existing wheelmapApiService as fallback
      const { default: wheelmapApiService } = await import('../services/wheelmapApiService.js');

      const result = await wheelmapApiService.searchAccessiblePlaces(bounds, {
        limit: 50,
        wheelchair: wheelchairFilter,
        category: selectedCategory === 'all' ? null : selectedCategory
      });

      if (result && result.places && result.places.length > 0) {
        console.log('✅ Loaded', result.places.length, 'places from local API');
        setPlaces(result.places);
        createMarkersFromWidgetData(result.places);
      } else {
        console.log('⚠️ No data from local API, creating test markers');
        createTestMarkers();
      }
    } catch (error) {
      console.error('❌ Local API fallback failed:', error);
      console.log('🧪 Creating test markers as final fallback');
      createTestMarkers();
    }
  };

  // Create test markers to verify the marker system works
  const createTestMarkers = () => {
    if (!map) {
      console.error('❌ Map not available for test markers');
      return;
    }

    console.log('🧪 Creating test markers around Halifax...');

    const testPlaces = [
      {
        name: { en: 'Test Restaurant - Accessible' },
        coordinates: [-63.5752, 44.6488], // [lng, lat]
        category: 'restaurant',
        wheelchair: 'yes'
      },
      {
        name: { en: 'Test Bank - Limited Access' },
        coordinates: [-63.5852, 44.6588], // [lng, lat]
        category: 'bank',
        wheelchair: 'limited'
      },
      {
        name: { en: 'Test Parking - Not Accessible' },
        coordinates: [-63.5652, 44.6388], // [lng, lat]
        category: 'parking',
        wheelchair: 'no'
      }
    ];

    createMarkersFromWidgetData(testPlaces);
  };

  // Create markers from widget data
  const createMarkersFromWidgetData = (places) => {
    console.log('🎯 Creating markers from widget data, places array:', places);
    clearMarkers();

    if (!map) {
      console.error('❌ Map not available for marker creation');
      return;
    }

    console.log('🗺️ Map is available, creating markers...');

    const newMarkers = places.map((place, index) => {
      console.log(`📍 Processing place ${index + 1}:`, place);

      // Handle different data formats
      const coords = place.geometry?.coordinates || place.coordinates;
      console.log(`📍 Coordinates for place ${index + 1}:`, coords);

      if (!coords) {
        console.log(`⚠️ No coordinates for place ${index + 1}, skipping`);
        return null;
      }

      const lng = coords[0];
      const lat = coords[1];

      console.log(`📍 Creating marker at lat: ${lat}, lng: ${lng}`);

      // Create custom marker element
      const markerElement = document.createElement('div');
      markerElement.style.backgroundImage = `url(${getAccessibilityIcon(place.properties?.wheelchair || place.wheelchair)})`;
      markerElement.style.width = '24px';
      markerElement.style.height = '24px';
      markerElement.style.backgroundSize = 'contain';
      markerElement.style.backgroundRepeat = 'no-repeat';
      markerElement.style.cursor = 'pointer';

      const marker = new mapboxgl.Marker(markerElement)
        .setLngLat([lng, lat])
        .addTo(map);

      console.log(`✅ Marker created for place ${index + 1}`);

      // Add click listener
      marker.getElement().addEventListener('click', () => {
        console.log('📍 Marker clicked');

        // Create popup
        const popup = new mapboxgl.Popup({ closeButton: true, closeOnClick: true })
          .setLngLat([lng, lat])
          .setHTML(createInfoWindowContent(place))
          .addTo(map);
      });

      return marker;
    }).filter(marker => marker !== null);

    setMarkers(newMarkers);
    console.log(`✅ Created ${newMarkers.length} accessibility markers`);
  };

  // Add markers to the map
  const addMarkersToMap = useCallback((placesData) => {
    if (!map) return;

    // Clear existing markers
    clearMarkers();

    const newMarkers = placesData.map(place => {
      const markerElement = createMarkerElement(place);

      const marker = new mapboxgl.Marker({
        element: markerElement,
        anchor: 'bottom'
      })
        .setLngLat(place.coordinates)
        .addTo(map);

      // Add popup with place information
      const popup = new mapboxgl.Popup({
        closeButton: true,
        closeOnClick: false,
        maxWidth: '300px'
      }).setHTML(createPopupContent(place));

      marker.setPopup(popup);

      return marker;
    });

    setMarkers(newMarkers);
  }, [map]);

  // Create marker element
  const createMarkerElement = (place) => {
    const markerEl = document.createElement('div');
    markerEl.className = 'wheelmap-marker';

    const accessibilityColor = place.color;
    const icon = place.icon;
    const name = place.name;

    markerEl.innerHTML = `
      <div class="marker-container" style="background-color: ${accessibilityColor}">
        <div class="marker-icon">${icon}</div>
        <div class="marker-glow"></div>
      </div>
    `;

    // Add click handler
    markerEl.addEventListener('click', () => {
      // Handle marker click
      console.log('Clicked on:', place.name);
    });

    return markerEl;
  };

  // Create popup content
  const createPopupContent = (place) => {
    const accessibilityDetails = place.accessibility;
    const features = accessibilityDetails.features.map(f => f.description).join(', ');

    return `
      <div class="wheelmap-popup">
        <div class="popup-header">
          <h3>${place.name}</h3>
          <div class="accessibility-badge" style="background-color: ${place.color}">
            ${place.wheelchair === 'yes' ? '♿ Accessible' : 
              place.wheelchair === 'limited' ? '♿ Limited' : 
              place.wheelchair === 'no' ? '❌ Not Accessible' : '❓ Unknown'}
          </div>
        </div>
        <div class="popup-content">
          <p><strong>Category:</strong> ${place.category}</p>
          ${place.address.street ? `<p><strong>Address:</strong> ${place.address.street}${place.address.housenumber ? ` ${place.address.housenumber}` : ''}</p>` : ''}
          ${features ? `<p><strong>Features:</strong> ${features}</p>` : ''}
          <p><strong>Accessibility Score:</strong> ${accessibilityDetails.rating}/100</p>
        </div>
        <div class="popup-footer">
          <a href="https://wheelmap.org/en/node/${place.id}" target="_blank" rel="noopener noreferrer">
            View on Wheelmap
          </a>
        </div>
      </div>
    `;
  };

  // Get accessibility icon based on wheelchair status
  const getAccessibilityIcon = (wheelchairStatus) => {
    switch (wheelchairStatus) {
      case 'yes':
        return 'data:image/svg+xml;charset=UTF-8,%3csvg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"%3e%3ccircle cx="12" cy="12" r="10" fill="%2300AA00" opacity="0.8"/%3e%3cpath d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-2 15l-5-5 1.41-1.41L10 14.17l7.59-7.59L19 8l-9 9z" fill="white"/%3e%3c/svg%3e';
      case 'limited':
        return 'data:image/svg+xml;charset=UTF-8,%3csvg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"%3e%3ccircle cx="12" cy="12" r="10" fill="%23FFAA00" opacity="0.8"/%3e%3ctext x="12" y="16" text-anchor="middle" fill="white" font-size="14" font-weight="bold"%3e!%3c/text%3e%3c/svg%3e';
      case 'no':
        return 'data:image/svg+xml;charset=UTF-8,%3csvg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"%3e%3ccircle cx="12" cy="12" r="10" fill="%23CC0000" opacity="0.8"/%3e%3cpath d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z" fill="white"/%3e%3c/svg%3e';
      default:
        return 'data:image/svg+xml;charset=UTF-8,%3csvg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"%3e%3ccircle cx="12" cy="12" r="10" fill="%23888888" opacity="0.8"/%3e%3ctext x="12" y="16" text-anchor="middle" fill="white" font-size="12"%3e?%3c/text%3e%3c/svg%3e';
    }
  };

  // Create popup content for Mapbox markers
  const createInfoWindowContent = (place) => {
    const name = place.properties?.name || place.name?.en || 'Accessible Place';
    const category = place.properties?.category || place.category || 'Unknown';
    const wheelchair = place.properties?.wheelchair || place.wheelchair || 'unknown';

    return `
      <div style="max-width: 300px; font-family: Arial, sans-serif; padding: 8px;">
        <h3 style="margin: 0 0 8px 0; color: #333; font-size: 16px; font-weight: bold;">${name}</h3>
        <div style="margin-bottom: 8px;">
          <span style="background: ${wheelchair === 'yes' ? '#00AA00' : wheelchair === 'limited' ? '#FFAA00' : '#CC0000'}; color: white; padding: 2px 6px; border-radius: 3px; font-size: 12px;">
            ${wheelchair === 'yes' ? '♿ Accessible' :
              wheelchair === 'limited' ? '♿ Limited' :
              wheelchair === 'no' ? '❌ Not Accessible' : '❓ Unknown'}
          </span>
        </div>
        <p style="margin: 4px 0;"><strong>Category:</strong> ${category}</p>
        ${place.properties?.address?.street ? `<p style="margin: 4px 0;"><strong>Address:</strong> ${place.properties.address.street}${place.properties.address.housenumber ? ` ${place.properties.address.housenumber}` : ''}</p>` : ''}
        ${place.properties?.phone ? `<p style="margin: 4px 0;"><strong>Phone:</strong> ${place.properties.phone}</p>` : ''}
        ${place.properties?.website ? `<p style="margin: 4px 0;"><a href="${place.properties.website}" target="_blank" rel="noopener noreferrer">Visit Website</a></p>` : ''}
      </div>
    `;
  };

  // Clear all markers
  const clearMarkers = useCallback(() => {
    markers.forEach(marker => marker.remove());
    setMarkers([]);
  }, [markers]);

  // Get accessibility categories
  const getAccessibilityCategories = () => {
    return [
      { id: 'all', name: 'All Categories', icon: '📍' },
      { id: 'restaurant', name: 'Restaurants', icon: '🍽️' },
      { id: 'parking', name: 'Parking', icon: '🅿️' },
      { id: 'toilet', name: 'Toilets', icon: '🚻' },
      { id: 'bank', name: 'Banks', icon: '🏦' },
      { id: 'hospital', name: 'Hospitals', icon: '🏥' },
      { id: 'hotel', name: 'Hotels', icon: '🏨' }
    ];
  };

  // Handle category change
  const handleCategoryChange = (category) => {
    setSelectedCategory(category);
  };

  // Handle wheelchair filter change
  const handleWheelchairFilterChange = (filter) => {
    setWheelchairFilter(filter);
  };

  if (!isVisible) {
    return null;
  }

  return (
    <div className="wheelmap-layer-controls">
      {/* Category Filter */}
      <div className="filter-section">
        <label className="filter-label">Category:</label>
        <select 
          value={selectedCategory} 
          onChange={(e) => handleCategoryChange(e.target.value)}
          className="filter-select"
        >
          {getAccessibilityCategories().map(category => (
            <option key={category.id} value={category.id}>
              {category.icon} {category.name}
            </option>
          ))}
        </select>
      </div>

      {/* Wheelchair Filter */}
      <div className="filter-section">
        <label className="filter-label">Accessibility:</label>
        <select 
          value={wheelchairFilter} 
          onChange={(e) => handleWheelchairFilterChange(e.target.value)}
          className="filter-select"
        >
          <option value="yes">♿ Fully Accessible</option>
          <option value="limited">⚠️ Limited Access</option>
          <option value="no">❌ Not Accessible</option>
          <option value="unknown">❓ Unknown</option>
        </select>
      </div>

      {/* Loading State */}
      {loading && (
        <div className="loading-indicator">
          <div className="spinner"></div>
          <span>Loading accessible places...</span>
        </div>
      )}

      {/* Error State */}
      {error && (
        <div className="error-message">
          <span>⚠️ {error}</span>
        </div>
      )}

      {/* Results Summary */}
      {places.length > 0 && !loading && (
        <div className="results-summary">
          <span>Found {places.length} accessible places</span>
        </div>
      )}

      {/* Legend */}
      <div className="wheelmap-legend">
        <div className="legend-item">
          <div className="legend-color" style={{ backgroundColor: '#4CAF50' }}></div>
          <span>Fully Accessible</span>
        </div>
        <div className="legend-item">
          <div className="legend-color" style={{ backgroundColor: '#FF9800' }}></div>
          <span>Limited Access</span>
        </div>
        <div className="legend-item">
          <div className="legend-color" style={{ backgroundColor: '#F44336' }}></div>
          <span>Not Accessible</span>
        </div>
        <div className="legend-item">
          <div className="legend-color" style={{ backgroundColor: '#9E9E9E' }}></div>
          <span>Unknown</span>
        </div>
      </div>
    </div>
  );
};

export default WheelmapLayer;
